const response = $json;
const results = response.results || [];
const notStarted = [];
const inProgress = [];

for (const page of results) {
  const props = page.properties || {};
  const titleParts = props['Task name']?.title || [];
  const title = titleParts.map(t => t.plain_text).join('');
  const status = props['Status']?.status?.name || 'Unknown';
  const priority = props['Priority']?.select?.name || 'None';
  const dueDate = props['Due date']?.date?.start || null;
  const effort = props['Effort level']?.select?.name || '';
  const taskTypes = (props['Task type']?.multi_select || []).map(t => t.name).join(', ');

  const task = { title, status, priority, due_date: dueDate, effort, task_type: taskTypes, url: page.url };

  if (status === 'In progress') inProgress.push(task);
  else notStarted.push(task);
}

let summary = '## Open Notion Tasks (' + results.length + ' total)\n\n';

if (inProgress.length > 0) {
  summary += '### In Progress (' + inProgress.length + ')\n';
  for (const t of inProgress) {
    const due = t.due_date ? ' | Due: ' + t.due_date : '';
    summary += '- **[' + t.priority + ']** ' + t.title + due + '\n';
  }
  summary += '\n';
}

if (notStarted.length > 0) {
  summary += '### Not Started (' + notStarted.length + ')\n';
  const sorted = notStarted.sort((a, b) => {
    const order = { High: 0, Medium: 1, Low: 2, None: 3 };
    return (order[a.priority] || 3) - (order[b.priority] || 3);
  });
  for (const t of sorted.slice(0, 20)) {
    const due = t.due_date ? ' | Due: ' + t.due_date : '';
    summary += '- **[' + t.priority + ']** ' + t.title + due + '\n';
  }
  if (notStarted.length > 20) summary += '- _...and ' + (notStarted.length - 20) + ' more_\n';
}

const today = new Date().toISOString().slice(0, 10);
const overdue = results.filter(p => {
  const due = p.properties?.['Due date']?.date?.start;
  return due && due < today;
});
if (overdue.length > 0) {
  summary += '\n### OVERDUE (' + overdue.length + ')\n';
  for (const p of overdue) {
    const title = (p.properties?.['Task name']?.title || []).map(t => t.plain_text).join('');
    const due = p.properties?.['Due date']?.date?.start;
    summary += '- ' + title + ' (was due ' + due + ')\n';
  }
}

return [{ json: {
  task_summary: summary,
  total_open: results.length,
  in_progress: inProgress.length,
  not_started: notStarted.length,
  overdue: overdue.length,
  generated_at: new Date().toISOString(),
  status: 'ready_for_brief'
} }];
